import { Mesh, PlaneGeometry, Group, Texture } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Create a container group
  const container = new Group();

  // Atlas region (fallback defaults)
  const atlasRect = config.atlasRegion ?? { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlasRect.width / atlasRect.height;

  // Plane geometry respecting the atlas aspect ratio
  const geometry = new PlaneGeometry(aspect, 1);

  // Node material – will receive texture later
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  // Mesh
  const sprite = new Mesh(geometry, material);
  sprite.renderOrder = 0;
  container.add(sprite);

  // Billboarding: orient toward camera each frame
  sprite.onBeforeRender = (renderer, scene, camera) => {
    // copy camera rotation (quaternion) to keep sprite facing the camera
    sprite.quaternion.copy(camera.quaternion);
  };

  // Load texture asynchronously (function remains synchronous)
  /** @type {Texture | null} */
  let loadedTexture = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      // Apply UV offset / repeat for atlas region if needed
      if (atlasRect.width && atlasRect.height) {
        // Assume the supplied texture is the whole atlas.
        // Compute UV transform based on atlas size (placeholder logic).
        // If atlas dimensions are unknown, keep default (full texture).
        // Here we simply set offset and repeat to map the region.
        // Users can adapt this if they expose atlas size elsewhere.
        const texWidth = tex.image?.width || atlasRect.width;
        const texHeight = tex.image?.height || atlasRect.height;

        const repeatX = atlasRect.width / texWidth;
        const repeatY = atlasRect.height / texHeight;
        const offsetX = atlasRect.x / texWidth;
        const offsetY = 1 - (atlasRect.y + atlasRect.height) / texHeight; // flip Y

        tex.offset.set(offsetX, offsetY);
        tex.repeat.set(repeatX, repeatY);
        tex.needsUpdate = true;
      }

      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // texture load failure – keep material empty
    });

  // No cinematic primitives for this node
  const primitiveHandles = [];

  // Populate userData for external systems
  container.userData.handlers = {}; // no interactions

  // Cleanup function
  container.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture if present
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    // Cleanup any primitive timelines/resources
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') {
        ph.cleanup();
      }
    }
  };

  return container;
}
